using System.Net.Mail;
using System.Threading.Channels;
using Microsoft.AspNetCore.Identity;

namespace F1RaceLens.Api.Accounts;

// Tokens are generated by a worker after the generic HTTP response, avoiding account lookup/delivery timing leaks.
public sealed class PasswordRecovery(IServiceScopeFactory scopes, IConfiguration configuration,
    ILogger<PasswordRecovery> logger, IHostEnvironment? environment = null, IAccountMailTransport? transport = null) : BackgroundService, IAccountMailQueue
{
    private readonly Channel<AccountMail> queue = Channel.CreateBounded<AccountMail>(new BoundedChannelOptions(64) {
        SingleReader = true, FullMode = BoundedChannelFullMode.Wait
    });
    private readonly string? host = configuration["PasswordRecovery:SmtpHost"];
    private readonly string? sender = configuration["PasswordRecovery:From"];
    private readonly string? origin = configuration["PasswordRecovery:PublicOrigin"];
    public bool Available => !string.IsNullOrWhiteSpace(host) && MailAddress.TryCreate(sender, out _)
        && !string.IsNullOrWhiteSpace(configuration["PasswordRecovery:Username"])
        && !string.IsNullOrWhiteSpace(configuration["PasswordRecovery:Password"])
        && configuration.GetValue("PasswordRecovery:SmtpPort", 587) is >= 1 and <= 65535
        && Uri.TryCreate(origin, UriKind.Absolute, out var uri)
        && (uri.Scheme == "https" || (environment?.IsDevelopment() == true && uri.Scheme == "http" && uri.IsLoopback))
        && string.IsNullOrEmpty(uri.UserInfo) && uri.AbsolutePath == "/" && string.IsNullOrEmpty(uri.Query) && string.IsNullOrEmpty(uri.Fragment);

    public bool Enqueue(string email) => Enqueue(new AccountMail(AccountMailKind.Recovery, email));
    public bool Enqueue(AccountMail mail) => queue.Writer.TryWrite(mail);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var mail in queue.Reader.ReadAllAsync(stoppingToken)) {
            try {
                if (!Available) continue;
                using var scope = scopes.CreateScope();
                var users = scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();
                var user = mail.Kind == AccountMailKind.Recovery
                    ? await users.FindByEmailAsync(mail.Email) : await users.FindByIdAsync(mail.UserId!);
                if (user is null) continue;
                var token = mail.Token;
                if (mail.Kind == AccountMailKind.Recovery) token = await users.GeneratePasswordResetTokenAsync(user);
                else if (mail.Kind == AccountMailKind.Confirmation && (user.Email != mail.Email || user.EmailConfirmed)) continue;
                // Fragment stays out of HTTP request URLs, server access logs and referrer headers.
                var path = mail.Kind switch { AccountMailKind.Recovery => "/reset-password", AccountMailKind.Confirmation => "/confirm-email", _ => "/confirm-email-change" };
                var link = origin!.TrimEnd('/') + path + "#user=" + Uri.EscapeDataString(user.Id) + "&token=" + Uri.EscapeDataString(token!);
                if (mail.Kind == AccountMailKind.EmailChange) link += "&email=" + Uri.EscapeDataString(mail.Email);
                var text = AccountMailText.Create(mail.Kind, user.Language, link);
                using var deadline = CancellationTokenSource.CreateLinkedTokenSource(stoppingToken);
                deadline.CancelAfter(TimeSpan.FromSeconds(15));
                await (transport ?? new SmtpAccountMailTransport(configuration)).SendAsync(mail.Email, text.Subject, text.Body, deadline.Token);
            }
            catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested) { break; }
            catch (Exception) {
                // Never log SMTP exceptions: they can contain recipients, credentials or message content.
                logger.LogWarning("Account email delivery failed. Check private SMTP configuration.");
            }
        }
    }
}
